dslRule:
/*!
@id: textprocessor.deprocess.labelprovider.text
@description: Wrap ILabelProvider.getText() calls with TextProcessor.deprocess() to remove BiDi markers. This is useful for preventing BiDi markers from appearing in copied text.
@severity: HINT
*/
org.eclipse.jface.viewers.ILabelProvider $provider.getText($element)
=>
org.eclipse.osgi.util.TextProcessor.deprocess($provider.getText($element))
;;

beforeExample:
package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jface.viewers.ILabelProvider;
import org.eclipse.swt.graphics.Image;

class MyLabelProvider implements ILabelProvider {
    @Override
    public Image getImage(Object element) { return null; }
    @Override
    public String getText(Object element) { return element.toString(); }
    @Override
    public void addListener(org.eclipse.jface.viewers.ILabelProviderListener listener) {}
    @Override
    public void dispose() {}
    @Override
    public boolean isLabelProperty(Object element, String property) { return false; }
    @Override
    public void removeListener(org.eclipse.jface.viewers.ILabelProviderListener listener) {}
}

public class TestClass {
    ILabelProvider fLabelProvider = new MyLabelProvider();

    public String getResourceName(Object resource) {
        return fLabelProvider.getText(resource);
    }

    public String getJavaElementName(IJavaElement javaElement) {
        return fLabelProvider.getText(javaElement);
    }
}

afterExample:
package test;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jface.viewers.ILabelProvider;
import org.eclipse.osgi.util.TextProcessor;
import org.eclipse.swt.graphics.Image;

class MyLabelProvider implements ILabelProvider {
    @Override
    public Image getImage(Object element) { return null; }
    @Override
    public String getText(Object element) { return element.toString(); }
    @Override
    public void addListener(org.eclipse.jface.viewers.ILabelProviderListener listener) {}
    @Override
    public void dispose() {}
    @Override
    public boolean isLabelProperty(Object element, String property) { return false; }
    @Override
    public void removeListener(org.eclipse.jface.viewers.ILabelProviderListener listener) {}
}

public class TestClass {
    ILabelProvider fLabelProvider = new MyLabelProvider();

    public String getResourceName(Object resource) {
        return TextProcessor.deprocess(fLabelProvider.getText(resource));
    }

    public String getJavaElementName(IJavaElement javaElement) {
        return TextProcessor.deprocess(fLabelProvider.getText(javaElement));
    }
}

negativeExample:
package test;

public class NegativeTestClass {
    public String getSimpleText() {
        return "some text";
    }

    class CustomObject {
        public String getText() { return "custom text"; }
    }

    public String getCustomObjectText() {
        CustomObject obj = new CustomObject();
        return obj.getText(); // Should not match: not called on ILabelProvider
    }

    public String getOtherText() {
        String s = "hello";
        return s; // No getText() call
    }
}
